# PreToolUse (Edit|Write): blocks edits to secrets, generated files and build output. Exit 2 = blocked.
$ErrorActionPreference = 'Stop'
try {
    $payload = [Console]::In.ReadToEnd() | ConvertFrom-Json
    $filePath = $payload.tool_input.file_path
    if (-not $filePath) { exit 0 }

    $projectDir = $env:CLAUDE_PROJECT_DIR ?? $payload.cwd
    $relative = [IO.Path]::GetRelativePath($projectDir, $filePath) -replace '\\', '/'
    $name = [IO.Path]::GetFileName($relative)
    $segments = $relative -split '/'

    $reason = switch -Regex ($relative) {
        { $name -like '.env*' } { "$relative holds environment secrets. Use user-secrets (dotnet user-secrets set ...) instead."; break }
        '\.(pfx|p12|pem|key|snk|cer|crt)$' { "$relative is a certificate or key. Never edit or create key material through Claude."; break }
        '^docs/openapi\.json$' { 'docs/openapi.json is generated by dotnet build. Change the controllers/contracts and rebuild instead.'; break }
        '(^|/)Migrations/' {
            if (Test-Path -LiteralPath $filePath) { "$relative is an existing migration. Never hand-edit migrations; add a new one with /add-migration." }
            break
        }
        { $segments -contains 'bin' -or $segments -contains 'obj' } { "$relative is build output (bin/obj). Edit the source instead."; break }
        { $segments -contains '.git' } { "$relative is inside .git. Use git commands instead."; break }
    }

    if ($reason) {
        [Console]::Error.WriteLine("Blocked by protect-files hook: $reason")
        exit 2
    }
    exit 0
}
catch {
    [Console]::Error.WriteLine("protect-files hook: allowing after unexpected error: $_")
    exit 0
}
